f2p:
custom-property-no-missing-var-function reject true 'a {
	--foo: red;
	--bar: blue;

	color: var(--foo, --bar);
}' var() with missing var() syntax on fallback

selector-disallowed-list reject [
  /^\.(foo)[,\s]?(?!\w).*$/,
  { ignore: [ 'inside-block' ], splitList: true }
] '/* a comment */
.foo, /* a comment */
.foo,
/* a comment */
.foo
{}' no description

named-grid-areas-no-invalid accept [ true ] '.test-grid {
	grid-template:
		"a a a"
		"b b	b";
}' Issue #8134 - tabs should be treated as valid whitespace separators
